"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { ChevronRight } from "@/components/ui/icons";

// Sidebar Item: generated by UIX from the design system. Same variants and sizes as the Figma component.

const sidebarItemClasses = "flex w-full items-center transition-colors h-10 px-3 gap-3 rounded-md text-label-medium text-fg-secondary hover:bg-subtle hover:text-fg-primary [&[aria-current=page]]:bg-brand-subtle [&[aria-current=page]]:text-fg-brand [&[aria-current=page]_svg]:text-icon-brand [&[aria-current=page]_[data-slot=count]]:bg-brand [&[aria-current=page]_[data-slot=count]]:text-fg-on-brand focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus aria-disabled:pointer-events-none aria-disabled:text-fg-disabled [&_svg]:size-5 [&_svg]:shrink-0 [&_svg]:text-icon-secondary";

export interface SidebarItemProps
  extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  /** Marks the current page: sets aria-current and the active look. */
  active?: boolean;
  disabled?: boolean;
  /** Icon before the label. */
  icon?: React.ReactNode;
  /** Count or tag after the label. */
  badge?: React.ReactNode;
  /** Chevron at the end. */
  trailingChevron?: boolean;
}

const SidebarItem = React.forwardRef<HTMLAnchorElement, SidebarItemProps>(
  ({ className, active = false, disabled = false, icon, badge, trailingChevron = false, children, ...props }, ref) => (
    <a data-slot="sidebar-item" data-kind="chip" ref={ref} aria-current={active ? "page" : void 0} aria-disabled={disabled || void 0} tabIndex={disabled ? -1 : props.tabIndex} className={cn(sidebarItemClasses, !active && "skin-quiet", className)} {...props}>
      {icon}
      <span className="min-w-0 flex-1 truncate">{children}</span>
      {badge != null ? <span data-slot="count" className="shrink-0 rounded-full bg-muted text-fg-secondary px-2 py-0-5 text-label-small">{badge}</span> : null}
      {trailingChevron ? <ChevronRight aria-hidden /> : null}
    </a>
  ),
);
SidebarItem.displayName = "SidebarItem";

const Sidebar = React.forwardRef<HTMLElement, React.HTMLAttributes<HTMLElement>>(({ className, ...props }, ref) => (
  <nav ref={ref} aria-label="Sidebar" data-slot="sidebar" data-kind="surface" className={cn("flex flex-col gap-1 px-3 py-4 bg-surface border border-line-default rounded-lg", className)} {...props} />
));
Sidebar.displayName = "Sidebar";

export { Sidebar, SidebarItem };
